<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { ref, onMounted } from "vue";
import { useAuth } from "@papilio/auth";
import { request, item, query, type PaymentDestination, type Page, type SmsOriginCapabilities } from "@papilio/api";
import { faNumber, asciiDigits } from "@papilio/ui";
import ReceivingAccountBindingModal from "./payments/ReceivingAccountBindingModal.vue";
const props=defineProps<{capabilities?:SmsOriginCapabilities|null}>();
const bindingOpen=ref(false),bindingDestination=ref<PaymentDestination|null>(null),revision=ref<number|undefined>();
const auth = useAuth(); const rows = ref<PaymentDestination[]>([]); const selected = ref<number | null>(null); const page = ref(1); const pages = ref(1); const q = ref(""); const state = ref<"loading" | "ready" | "error">("loading"); const busy = ref(false); const error = ref(""); const notice = ref(""); let version = 0;
const empty = () => ({ title:"",kind:"card" as PaymentDestination["kind"],account:"",recipient:"",bank_name:"",instructions:"",is_active:false }); const form = ref(empty());
async function load(): Promise<void> { const stamp = ++version; state.value="loading"; error.value=""; try { const result = await request<Page<PaymentDestination>>(`/v1/admin/payments/destinations?${query({page:page.value,q:q.value})}`); if (stamp !== version) return; rows.value=result.data; pages.value=result.meta.pager?.total_pages ?? 1; state.value="ready"; } catch (cause) { if (stamp === version) { state.value="error"; error.value=cause instanceof Error ? cause.message : "The operation failed. Please try again."; } } }
function choose(row: PaymentDestination, force=false): void { if(busy.value&&!force)return; editorOpen.value=true; selected.value=row.destination_id; revision.value=row.revision; form.value={ title:row.title,kind:row.kind,account:row.account,recipient:row.recipient,bank_name:row.bank_name,instructions:row.instructions ?? "",is_active:row.is_active }; notice.value=""; }
async function save(): Promise<void> { if(busy.value||!auth.can("payments",selected.value===null?"create":"update"))return; busy.value=true; error.value=""; notice.value=""; try { const result=await item<PaymentDestination>(`/v1/admin/payments/destinations${selected.value === null ? '' : '/' + selected.value}`,selected.value === null ? "POST" : "PUT",{...form.value,...(selected.value!==null&&revision.value!==undefined?{expected_revision:revision.value}:{}),account:asciiDigits(form.value.account.trim()).toUpperCase(),instructions:form.value.instructions.trim() || null}); choose(result,true); editorOpen.value=false; notice.value="Payment destination saved. Existing requests retain their original instructions."; await load(); } catch(cause) { error.value=cause instanceof Error ? cause.message : "The operation failed. Please try again."; } finally { busy.value=false; } }
const editorOpen=ref(false);
function startCreate():void{if(busy.value)return;if(selected.value!==null){selected.value=null;form.value=empty();}notice.value="";editorOpen.value=true;}
onMounted(load);
</script>
<template><section class="card card-pad" style="margin-top:18px"><h2>Payment destinations</h2><p>Manage bank cards, IBANs and accounts. Each top-up retains its selected destination details.</p><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><div class="toolbar"><label class="field"><span>Search destinations</span><input v-model="q" @keydown.enter="page=1; load()" /></label><button class="btn secondary" @click="page=1; load()">Search</button><button v-if="auth.can('payments','create')" class="btn" @click="startCreate" :disabled="busy">Create destination</button></div><p v-if="state==='loading'">Loading…</p><p v-else-if="state==='ready' && !rows.length">No destinations found.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Label</th><th>Bank</th><th>Status</th><th v-if="capabilities?.read_available">Receiving account</th></tr></thead><tbody><tr v-for="row in rows" :key="row.destination_id" tabindex="0" :class="{'selected-row':selected===row.destination_id}" @click="choose(row)" @keydown.enter="choose(row)"><td>{{ row.title }}</td><td>{{ row.bank_name }}</td><td>{{ row.is_active ? 'Active' : 'Inactive' }}</td><td v-if="capabilities?.read_available"><span>{{row.receiving_alias_id==null?'Unbound':'Alias #'+row.receiving_alias_id}}</span><button v-if="capabilities.enabled&&auth.can('payments','update')" class="btn small secondary" :disabled="busy" @click.stop="bindingDestination=row;bindingOpen=true">Bind receiving account</button></td></tr></tbody></table></div><div class="pager"><button :disabled="page<=1" @click="page--; load()">‹</button><span>{{ faNumber(page) }}</span><button :disabled="page>=pages" @click="page++; load()">›</button></div><Modal v-model="editorOpen" :title="selected===null?'Create destination':'Edit payment destination'" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="save"><fieldset class="form-grid" :disabled="busy || !auth.can('payments', selected === null ? 'create' : 'update')"><label class="field"><span>Destination name</span><input v-model="form.title" required maxlength="100" /></label><label class="field"><span>Transfer method</span><select v-model="form.kind"><option value="card">Bank card</option><option value="iban">IBAN</option><option value="bank_account">Bank account</option></select></label><label class="field"><span>Destination account</span><input v-model="form.account" dir="ltr" required maxlength="100" /></label><label class="field"><span>Recipient name</span><input v-model="form.recipient" required maxlength="100" /></label><label class="field"><span>Bank name</span><input v-model="form.bank_name" required maxlength="100" /></label><label class="field"><span>Destination instructions</span><textarea v-model="form.instructions" maxlength="2000" /></label><label class="check-row"><input v-model="form.is_active" type="checkbox" />Available to customers</label><button class="btn">Save destination</button></fieldset></form></Modal><ReceivingAccountBindingModal v-model="bindingOpen" :destination="bindingDestination" :capabilities="capabilities??null" @saved="load"/></section></template>
